"""可序列化的量子电路 IR：校验、规范化与确定性等价变换。

IR 全部由 JSON 原生类型组成（dict / list / str / int / float / bool / None），
不依赖任何第三方量子 SDK。规范化后的电路形如::

    {
        "qubit_count": 2,
        "parameters": ["theta"],
        "operations": [
            {"gate": "x", "target": 0},
            {"gate": "cx", "control": 0, "target": 1},
            {"gate": "rx", "target": 0, "angle": 1.5},
            {"gate": "rz", "target": 1,
             "angle": {"parameter": "theta", "coefficient": 1.0, "offset": 0.0}},
        ],
    }

常量旋转角规范化为 JSON 数字；参数化旋转角为
``{"parameter", "coefficient", "offset"}`` 线性表达式。
"""

from __future__ import annotations

import math
from typing import Any

__all__ = [
    "CircuitValidationError",
    "ParameterBindingError",
    "normalize_circuit",
    "simplify_circuit",
    "bind_parameters",
]

_TWO_PI = 2.0 * math.pi

_INVOLUTIONS = ("x", "h", "cx")
_ROTATIONS = ("rx", "rz")
_KNOWN_GATES = ("x", "h", "rx", "rz", "cx")

_EXPECTED_FIELDS = {
    "x": frozenset(("gate", "target")),
    "h": frozenset(("gate", "target")),
    "cx": frozenset(("gate", "control", "target")),
    "rx": frozenset(("gate", "target", "angle")),
    "rz": frozenset(("gate", "target", "angle")),
}
_TOP_FIELDS = frozenset(("qubit_count", "parameters", "operations"))
_ANGLE_FIELDS = frozenset(("parameter", "coefficient", "offset"))


class CircuitValidationError(ValueError):
    """电路 IR 校验失败。

    ``code`` 为稳定的机器可读错误码，``path`` 指向输入中出错的位置
    （根对象为 ``"$"``，数组元素形如 ``"operations[0].target"``）。
    每次校验只报告按输入顺序遇到的首个错误。
    """

    def __init__(self, code: str, path: str, message: str | None = None) -> None:
        self.code = code
        self.path = path
        if message is None:
            message = f"{code} at {path}"
        super().__init__(message)


class ParameterBindingError(ValueError):
    """参数绑定失败。缺失参数 code 为 ``missing_parameter``，
    未知参数为 ``unknown_parameter``；同类多个名称按字典序取首个。"""

    def __init__(self, code: str, path: str, message: str | None = None) -> None:
        self.code = code
        self.path = path
        if message is None:
            message = f"{code} at {path}"
        super().__init__(message)


# ---------------------------------------------------------------------------
# 基础判断
# ---------------------------------------------------------------------------

def _is_int(value: Any) -> bool:
    """JSON 整数；bool 是 int 的子类，但不算数值。"""
    return isinstance(value, int) and not isinstance(value, bool)


def _is_number(value: Any) -> bool:
    """有限/无限 JSON 实数（int 或 float），排除布尔值。"""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _canon_float(value: float) -> float:
    """统一浮点形态：抹掉 -0.0。"""
    if value == 0.0:
        return 0.0
    return value


def _finite_float(value: Any, path: str) -> float:
    """把 JSON 实数转为有限 float；NaN/无穷/溢出统一报 non_finite_number。"""
    result = float(value)
    if not math.isfinite(result):
        raise CircuitValidationError("non_finite_number", path, f"number at {path} must be finite")
    return _canon_float(result)


# ---------------------------------------------------------------------------
# 校验与规范化
# ---------------------------------------------------------------------------

def _validate_qubit(op: dict, key: str, path: str, qubit_count: int) -> int:
    if key not in op:
        raise CircuitValidationError("missing_field", path, f"missing field {path}")
    value = op[key]
    if not _is_int(value):
        raise CircuitValidationError("invalid_type", path, f"field {path} must be an integer qubit index")
    if value < 0 or value >= qubit_count:
        raise CircuitValidationError("qubit_out_of_range", path, f"qubit index {value} out of range at {path}")
    return value


def _validate_angle(raw: Any, path: str, parameters: list[str]) -> Any:
    if _is_number(raw):
        angle = float(raw)
        if not math.isfinite(angle):
            raise CircuitValidationError("non_finite_number", path, f"angle at {path} must be finite")
        return _canon_float(angle)

    if not isinstance(raw, dict):
        raise CircuitValidationError("invalid_type", path, f"angle at {path} must be a number or parameter expression")

    for key in raw:
        if not isinstance(key, str) or key not in _ANGLE_FIELDS:
            key_path = f"{path}.{key}" if isinstance(key, str) else path
            raise CircuitValidationError("unknown_field", key_path, f"unknown angle field at {key_path}")

    if "parameter" not in raw:
        raise CircuitValidationError("missing_field", f"{path}.parameter", f"missing field {path}.parameter")
    name = raw["parameter"]
    if not isinstance(name, str):
        raise CircuitValidationError("invalid_type", f"{path}.parameter", f"field {path}.parameter must be a string")
    if name not in parameters:
        raise CircuitValidationError("unknown_parameter", f"{path}.parameter", f"undeclared parameter {name!r} at {path}.parameter")

    coefficient = 1.0
    if "coefficient" in raw:
        value = raw["coefficient"]
        if not _is_number(value):
            raise CircuitValidationError("invalid_type", f"{path}.coefficient", f"field {path}.coefficient must be a number")
        coefficient = _finite_float(value, f"{path}.coefficient")

    offset = 0.0
    if "offset" in raw:
        value = raw["offset"]
        if not _is_number(value):
            raise CircuitValidationError("invalid_type", f"{path}.offset", f"field {path}.offset must be a number")
        offset = _finite_float(value, f"{path}.offset")

    # 系数为 0 的参数表达式与常量等价，规范化为数字形式。
    if coefficient == 0.0:
        return _canon_float(offset)
    return {"parameter": name, "coefficient": _canon_float(coefficient), "offset": _canon_float(offset)}


def _validate_operation(raw: Any, index: int, qubit_count: int, parameters: list[str]) -> dict:
    path = f"operations[{index}]"
    if not isinstance(raw, dict):
        raise CircuitValidationError("invalid_type", path, f"operation at {path} must be an object")

    if "gate" not in raw:
        raise CircuitValidationError("missing_field", f"{path}.gate", f"missing field {path}.gate")
    gate = raw["gate"]
    if not isinstance(gate, str):
        raise CircuitValidationError("invalid_type", f"{path}.gate", f"field {path}.gate must be a string")
    if gate not in _KNOWN_GATES:
        raise CircuitValidationError("unknown_gate", f"{path}.gate", f"unknown gate {gate!r} at {path}.gate")

    expected = _EXPECTED_FIELDS[gate]
    for key in raw:
        if not isinstance(key, str) or key not in expected:
            key_path = f"{path}.{key}" if isinstance(key, str) else path
            raise CircuitValidationError("unknown_field", key_path, f"unknown field at {key_path}")

    if gate == "cx":
        control = _validate_qubit(raw, "control", f"{path}.control", qubit_count)
        target = _validate_qubit(raw, "target", f"{path}.target", qubit_count)
        if control == target:
            raise CircuitValidationError(
                "control_target_same", f"{path}.control", f"cx control and target must differ at {path}"
            )
        return {"gate": "cx", "control": control, "target": target}

    target = _validate_qubit(raw, "target", f"{path}.target", qubit_count)
    if gate in ("x", "h"):
        return {"gate": gate, "target": target}

    # rx / rz
    if "angle" not in raw:
        raise CircuitValidationError("missing_field", f"{path}.angle", f"missing field {path}.angle")
    angle = _validate_angle(raw["angle"], f"{path}.angle", parameters)
    return {"gate": gate, "target": target, "angle": angle}


def normalize_circuit(data: Any) -> dict:
    """校验 JSON 兼容的电路描述并返回规范化的新对象，不修改输入。

    省略的 ``parameters`` / ``operations`` 补为空列表；旋转角统一为
    float 或完整的参数线性表达式；相同语义的输入得到字段形式一致的结果。
    """
    if not isinstance(data, dict):
        raise CircuitValidationError("invalid_type", "$", "circuit must be a JSON object")

    # 先按输入（字典插入）顺序拒绝未知字段。
    for key in data:
        if not isinstance(key, str) or key not in _TOP_FIELDS:
            path = key if isinstance(key, str) else "$"
            raise CircuitValidationError("unknown_field", path, f"unknown top-level field {path!r}")

    if "qubit_count" not in data:
        raise CircuitValidationError("missing_field", "qubit_count", "missing field qubit_count")
    qubit_count = data["qubit_count"]
    if not _is_int(qubit_count):
        raise CircuitValidationError("invalid_type", "qubit_count", "qubit_count must be a non-negative integer")
    if qubit_count < 0:
        raise CircuitValidationError("invalid_value", "qubit_count", "qubit_count must be non-negative")

    parameters: list[str] = []
    if "parameters" in data:
        raw_parameters = data["parameters"]
        if not isinstance(raw_parameters, list):
            raise CircuitValidationError("invalid_type", "parameters", "parameters must be an array of strings")
        seen: set[str] = set()
        for i, name in enumerate(raw_parameters):
            path = f"parameters[{i}]"
            if not isinstance(name, str):
                raise CircuitValidationError("invalid_type", path, f"parameter name at {path} must be a string")
            if name == "":
                raise CircuitValidationError("invalid_parameter_name", path, f"parameter name at {path} must be non-empty")
            if name in seen:
                raise CircuitValidationError("duplicate_parameter", path, f"duplicate parameter name {name!r} at {path}")
            seen.add(name)
            parameters.append(name)

    operations: list[dict] = []
    if "operations" in data:
        raw_operations = data["operations"]
        if not isinstance(raw_operations, list):
            raise CircuitValidationError("invalid_type", "operations", "operations must be an array")
        for i, raw_op in enumerate(raw_operations):
            operations.append(_validate_operation(raw_op, i, qubit_count, parameters))

    return {"qubit_count": qubit_count, "parameters": parameters, "operations": operations}


# ---------------------------------------------------------------------------
# simplify：确定性等价变换
# ---------------------------------------------------------------------------

def _wrap_angle(value: float) -> float:
    """规约到半开区间 [-pi, pi)。"""
    wrapped = (value + math.pi) % _TWO_PI - math.pi
    return _canon_float(wrapped)


def _touches(operation: dict, qubit: int) -> bool:
    if operation["gate"] == "cx":
        return operation["control"] == qubit or operation["target"] == qubit
    return operation["target"] == qubit


def _same_involution(left: dict, right: dict) -> bool:
    """两个相邻的 x/h/cx 作用位是否完全相同（调用时 gate 已一致）。"""
    if left["gate"] != right["gate"]:
        return False
    if left["target"] != right["target"]:
        return False
    if left["gate"] == "cx":
        return left["control"] == right["control"]
    return True


def _add_angles(left: Any, right: Any) -> Any:
    """合并两个同轴旋转角。

    常量与常量、参数与同参数表达式可精确合并；不同参数的表达式返回 None，
    调用方据此保持原顺序。返回的常量不做零判定，由调用方统一规约。
    """
    if isinstance(left, float) and isinstance(right, float):
        return _canon_float(left + right)

    if isinstance(left, float):
        return {
            "parameter": right["parameter"],
            "coefficient": _canon_float(right["coefficient"]),
            "offset": _canon_float(right["offset"] + left),
        }
    if isinstance(right, float):
        return {
            "parameter": left["parameter"],
            "coefficient": _canon_float(left["coefficient"]),
            "offset": _canon_float(left["offset"] + right),
        }

    if left["parameter"] != right["parameter"]:
        return None
    coefficient = _canon_float(left["coefficient"] + right["coefficient"])
    offset = _canon_float(left["offset"] + right["offset"])
    if coefficient == 0.0:
        return _canon_float(offset)
    return {"parameter": left["parameter"], "coefficient": coefficient, "offset": offset}


def _canonicalize_angle(angle: Any) -> Any:
    """simplify 输出角度的统一形态：常量包裹到 [-pi, pi)，参数表达式折叠常量偏移。"""
    if isinstance(angle, float):
        return _wrap_angle(angle)
    coefficient = angle["coefficient"]
    if coefficient == 0.0:
        return _wrap_angle(angle["offset"])
    return {
        "parameter": angle["parameter"],
        "coefficient": _canon_float(coefficient),
        "offset": _wrap_angle(angle["offset"]),
    }


def simplify_circuit(circuit: Any) -> dict:
    """对规范化电路做确定性等价变换。

    - 相邻且作用位相同的两个 x/h/cx 相互抵消；
    - 同轴、同目标位且中间没有作用于该位的操作的 rx/rz 合并；
    - 常量角规约到 [-pi, pi)，规约为零则删除；
    - 参数化旋转仅在线性表达式可精确合并时处理，否则保持原顺序。

    返回 ``{"circuit", "removed_operations", "merged_operations"}``，
    其中 circuit 为全新的合法规范 IR；重复简化结果不变。
    """
    normalized = normalize_circuit(circuit)

    kept: list[dict] = []
    removed = 0
    merged = 0

    for op in normalized["operations"]:
        gate = op["gate"]

        if gate in _INVOLUTIONS:
            if kept and _same_involution(kept[-1], op):
                kept.pop()
                removed += 2
            else:
                kept.append(dict(op))
            continue

        # rx / rz
        angle: Any = op["angle"]
        if isinstance(angle, float):
            angle = _wrap_angle(angle)
            if angle == 0.0:
                removed += 1
                continue

        # 向前找最近一个作用于目标位的操作：只有同轴旋转可以合并，
        # 其间的操作若都不触碰目标位，则旋转与之交换、合并安全。
        merge_index: int | None = None
        for j in range(len(kept) - 1, -1, -1):
            if _touches(kept[j], op["target"]):
                if kept[j]["gate"] == gate:
                    merge_index = j
                break

        if merge_index is not None:
            combined = _add_angles(kept[merge_index]["angle"], angle)
            if combined is not None:
                merged += 1
                if isinstance(combined, float) and _wrap_angle(combined) == 0.0:
                    del kept[merge_index]
                    removed += 1
                else:
                    kept[merge_index]["angle"] = _canonicalize_angle(combined)
                continue

        kept.append({"gate": gate, "target": op["target"], "angle": _canonicalize_angle(angle)})

    result = {
        "qubit_count": normalized["qubit_count"],
        "parameters": list(normalized["parameters"]),
        "operations": kept,
    }
    return {"circuit": result, "removed_operations": removed, "merged_operations": merged}


# ---------------------------------------------------------------------------
# bind：参数绑定
# ---------------------------------------------------------------------------

def bind_parameters(circuit: Any, values: Any) -> dict:
    """用 ``values`` 映射把电路参数替换为有限实数角度，返回全新电路。

    全部参数必须且只能绑定一次：缺失参数抛 ``missing_parameter``，
    未知绑定抛 ``unknown_parameter``（同类多个名称按字典序取首个）。
    成功后 ``parameters`` 为空且不存在参数化角度；输入电路与映射均不修改。
    """
    normalized = normalize_circuit(circuit)
    declared = normalized["parameters"]

    if not isinstance(values, dict):
        raise ParameterBindingError("invalid_type", "$", "parameter bindings must be an object")

    for key in values:
        if not isinstance(key, str):
            raise ParameterBindingError("invalid_type", "$", "parameter names must be strings")

    # 绑定值本身的类型/数值错误按映射插入顺序报告。
    for name, value in values.items():
        if not _is_number(value):
            raise ParameterBindingError("invalid_type", name, f"binding for {name!r} must be a finite number")
        if not math.isfinite(float(value)):
            raise ParameterBindingError("non_finite_number", name, f"binding for {name!r} must be finite")

    missing = sorted(name for name in declared if name not in values)
    if missing:
        name = missing[0]
        raise ParameterBindingError("missing_parameter", name, f"missing binding for parameter {name!r}")

    unknown = sorted(name for name in values if name not in declared)
    if unknown:
        name = unknown[0]
        raise ParameterBindingError("unknown_parameter", name, f"unknown parameter binding {name!r}")

    operations: list[dict] = []
    for i, op in enumerate(normalized["operations"]):
        if op["gate"] in _INVOLUTIONS:
            operations.append(dict(op))
            continue

        angle = op["angle"]
        if isinstance(angle, float):
            bound_angle = _canon_float(angle)
        else:
            name = angle["parameter"]
            bound_angle = angle["coefficient"] * float(values[name]) + angle["offset"]
            if not math.isfinite(bound_angle):
                raise ParameterBindingError(
                    "non_finite_number",
                    f"operations[{i}].angle",
                    f"bound angle at operations[{i}].angle is not finite",
                )
            bound_angle = _canon_float(bound_angle)
        operations.append({"gate": op["gate"], "target": op["target"], "angle": bound_angle})

    return {
        "qubit_count": normalized["qubit_count"],
        "parameters": [],
        "operations": operations,
    }

"""无噪声状态向量仿真与 Pauli 期望值估计。

仿真从全零态出发，qubit 0 对应状态索引的最低有效位；旋转门采用
``exp(-iθP/2)`` 约定（``rx(π)`` 把 ``|0⟩`` 映到 ``-i|1⟩``）。
observable 是长度等于 ``qubit_count`` 的 Pauli 串，字符 ``I/X/Y/Z``
的下标即量子位编号，结果按输入顺序返回。

省略 ``shots`` 时返回精确浮点期望值；给出 ``shots`` 时对每个
observable 独立采样 ``shots`` 次，返回正一/负一计数及由计数得到的
期望值。相同输入与 ``seed`` 产生完全相同的结果；采样 RNG 按
``f"{seed}:{index}"`` 派生，各项计数只依赖 seed、序号与 shots。

:func:`estimate_gradient` 在精确期望值基础上给出参数移位梯度：
仅覆盖 rx/rz 的线性参数角，按声明参数顺序返回各 observable 的
精确导数。

可选的 ``noise`` 描述逐门局部退极化噪声：``x``/``h``/``rx``/``rz``
之后在目标位施加单比特通道，``cx`` 之后在 control/target 两位上施加
双比特通道；子系统 S 上概率 p 的通道为
``D_S(ρ) = (1-p)ρ + p (I_S/2^|S| ⊗ Tr_S ρ)``，顺序与电路 IR 一致。
任一概率非零时改用密度矩阵精确仿真，量子位上限降为 10；``noise``
省略、为 None、为空对象或概率全零时行为与无噪声实现完全一致。
"""

from __future__ import annotations

import math
import random
from typing import Any

from .circuit import bind_parameters, normalize_circuit

__all__ = ["SimulationError", "estimate_expectation", "estimate_gradient"]

_MAX_QUBITS = 20
_MAX_QUBITS_NOISY = 10
_PAULI_CHARS = frozenset("IXYZ")
_INV_SQRT2 = 1.0 / math.sqrt(2.0)
_NOISE_FIELDS = ("single_qubit_depolarizing", "two_qubit_depolarizing")
_NOISE_FIELD_SET = frozenset(_NOISE_FIELDS)


class SimulationError(ValueError):
    """仿真入口校验失败。

    ``code`` 为稳定的机器可读错误码，``path`` 指向输入中出错的位置，
    语义与 :class:`qubitfabric.circuit.CircuitValidationError` 一致。
    """

    def __init__(self, code: str, path: str, message: str | None = None) -> None:
        self.code = code
        self.path = path
        if message is None:
            message = f"{code} at {path}"
        super().__init__(message)


def _is_int(value: Any) -> bool:
    """JSON 整数；bool 是 int 的子类，但不算数值。"""
    return isinstance(value, int) and not isinstance(value, bool)


def _is_number(value: Any) -> bool:
    """JSON 实数（int 或 float），排除布尔值。"""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _canon_float(value: float) -> float:
    """统一浮点形态：抹掉 -0.0。"""
    if value == 0.0:
        return 0.0
    return value


# ---------------------------------------------------------------------------
# 状态向量仿真
# ---------------------------------------------------------------------------

def _apply_x(state: list[complex], size: int, q: int) -> None:
    step = 1 << q
    for base in range(0, size, 2 * step):
        for off in range(step):
            i = base + off
            j = i + step
            state[i], state[j] = state[j], state[i]


def _apply_h(state: list[complex], size: int, q: int) -> None:
    step = 1 << q
    for base in range(0, size, 2 * step):
        for off in range(step):
            i = base + off
            j = i + step
            a = state[i]
            b = state[j]
            state[i] = (a + b) * _INV_SQRT2
            state[j] = (a - b) * _INV_SQRT2


def _apply_rx(state: list[complex], size: int, q: int, angle: float) -> None:
    half = angle / 2.0
    c = math.cos(half)
    ms = -1j * math.sin(half)
    step = 1 << q
    for base in range(0, size, 2 * step):
        for off in range(step):
            i = base + off
            j = i + step
            a = state[i]
            b = state[j]
            state[i] = c * a + ms * b
            state[j] = ms * a + c * b


def _apply_rz(state: list[complex], size: int, q: int, angle: float) -> None:
    half = angle / 2.0
    lo = complex(math.cos(half), -math.sin(half))
    hi = complex(math.cos(half), math.sin(half))
    step = 1 << q
    for base in range(0, size, 2 * step):
        for off in range(step):
            i = base + off
            state[i] *= lo
            state[i + step] *= hi


def _apply_cx(state: list[complex], size: int, control: int, target: int) -> None:
    cmask = 1 << control
    tmask = 1 << target
    for i in range(size):
        if (i & cmask) and not (i & tmask):
            j = i | tmask
            state[i], state[j] = state[j], state[i]


def _simulate(circuit: dict) -> list[complex]:
    """执行无参数电路，返回末态状态向量。"""
    size = 1 << circuit["qubit_count"]
    state = [0j] * size
    state[0] = 1 + 0j
    for op in circuit["operations"]:
        gate = op["gate"]
        if gate == "x":
            _apply_x(state, size, op["target"])
        elif gate == "h":
            _apply_h(state, size, op["target"])
        elif gate == "cx":
            _apply_cx(state, size, op["control"], op["target"])
        elif gate == "rx":
            _apply_rx(state, size, op["target"], op["angle"])
        else:  # rz
            _apply_rz(state, size, op["target"], op["angle"])
    return state


# ---------------------------------------------------------------------------
# 含噪密度矩阵仿真
# ---------------------------------------------------------------------------
#
# 密度矩阵按行主序扁平存储（rho[i * size + j]）。每个门之后按电路顺序
# 施加局部退极化通道 D_S(ρ) = (1-p)ρ + p (I_S/2^|S| ⊗ Tr_S ρ)。

def _dm_apply_single(
    rho: list[complex], size: int, q: int,
    u00: complex, u01: complex, u10: complex, u11: complex,
) -> None:
    """原地执行 ρ ← U ρ U†，U 为作用在量子位 q 上的 2x2 酉矩阵。"""
    step = 1 << q
    cu00 = u00.conjugate()
    cu01 = u01.conjugate()
    cu10 = u10.conjugate()
    cu11 = u11.conjugate()
    for rbase in range(0, size, 2 * step):
        for roff in range(step):
            row0 = (rbase + roff) * size
            row1 = row0 + step * size
            for cbase in range(0, size, 2 * step):
                for coff in range(step):
                    j0 = cbase + coff
                    j1 = j0 + step
                    a = rho[row0 + j0]
                    b = rho[row0 + j1]
                    c = rho[row1 + j0]
                    d = rho[row1 + j1]
                    t00 = u00 * a + u01 * c
                    t01 = u00 * b + u01 * d
                    t10 = u10 * a + u11 * c
                    t11 = u10 * b + u11 * d
                    rho[row0 + j0] = t00 * cu00 + t01 * cu01
                    rho[row0 + j1] = t00 * cu10 + t01 * cu11
                    rho[row1 + j0] = t10 * cu00 + t11 * cu01
                    rho[row1 + j1] = t10 * cu10 + t11 * cu11


def _dm_apply_cx(rho: list[complex], size: int, control: int, target: int) -> None:
    """原地执行 ρ ← C ρ C，C 为 cx 对应的置换（自逆）。"""
    cmask = 1 << control
    tmask = 1 << target
    for i in range(size):
        if (i & cmask) and not (i & tmask):
            ri = i * size
            rj = (i | tmask) * size
            for k in range(size):
                rho[ri + k], rho[rj + k] = rho[rj + k], rho[ri + k]
    for j in range(size):
        if (j & cmask) and not (j & tmask):
            j2 = j | tmask
            for i in range(size):
                base = i * size
                rho[base + j], rho[base + j2] = rho[base + j2], rho[base + j]


def _dm_depolarize_single(rho: list[complex], size: int, q: int, p: float) -> None:
    """原地施加单比特退极化通道：(1-p)ρ + p (I_q/2 ⊗ Tr_q ρ)。"""
    keep = 1.0 - p
    half_p = p / 2.0
    step = 1 << q
    for rbase in range(0, size, 2 * step):
        for roff in range(step):
            row0 = (rbase + roff) * size
            row1 = row0 + step * size
            for cbase in range(0, size, 2 * step):
                for coff in range(step):
                    j0 = cbase + coff
                    j1 = j0 + step
                    a = rho[row0 + j0]
                    b = rho[row0 + j1]
                    c = rho[row1 + j0]
                    d = rho[row1 + j1]
                    mix = (a + d) * half_p
                    rho[row0 + j0] = keep * a + mix
                    rho[row0 + j1] = keep * b
                    rho[row1 + j0] = keep * c
                    rho[row1 + j1] = keep * d + mix


def _dm_depolarize_two(rho: list[complex], size: int, q1: int, q2: int, p: float) -> None:
    """原地施加双比特退极化通道：(1-p)ρ + p (I_{q1,q2}/4 ⊗ Tr_{q1,q2} ρ)。"""
    keep = 1.0 - p
    quarter_p = p / 4.0
    m1 = 1 << q1
    m2 = 1 << q2
    both = m1 | m2
    for i in range(size):
        if i & both:
            continue
        rows = (i * size, (i | m1) * size, (i | m2) * size, (i | both) * size)
        for j in range(size):
            if j & both:
                continue
            cols = (j, j | m1, j | m2, j | both)
            mix = (
                rho[rows[0] + cols[0]]
                + rho[rows[1] + cols[1]]
                + rho[rows[2] + cols[2]]
                + rho[rows[3] + cols[3]]
            ) * quarter_p
            for a in range(4):
                base = rows[a]
                for b in range(4):
                    idx = base + cols[b]
                    rho[idx] = keep * rho[idx] + (mix if a == b else 0j)


def _simulate_noisy(circuit: dict, p1: float, p2: float) -> list[complex]:
    """执行无参数电路并逐门施加退极化通道，返回末态密度矩阵。"""
    size = 1 << circuit["qubit_count"]
    rho = [0j] * (size * size)
    rho[0] = 1 + 0j
    for op in circuit["operations"]:
        gate = op["gate"]
        target = op["target"]
        if gate == "x":
            _dm_apply_single(rho, size, target, 0j, 1 + 0j, 1 + 0j, 0j)
        elif gate == "h":
            _dm_apply_single(rho, size, target, _INV_SQRT2, _INV_SQRT2, _INV_SQRT2, -_INV_SQRT2)
        elif gate == "cx":
            _dm_apply_cx(rho, size, op["control"], target)
            if p2 != 0.0:
                _dm_depolarize_two(rho, size, op["control"], target, p2)
            continue
        elif gate == "rx":
            half = op["angle"] / 2.0
            ms = -1j * math.sin(half)
            _dm_apply_single(rho, size, target, math.cos(half), ms, ms, math.cos(half))
        else:  # rz
            half = op["angle"] / 2.0
            lo = complex(math.cos(half), -math.sin(half))
            hi = complex(math.cos(half), math.sin(half))
            _dm_apply_single(rho, size, target, lo, 0j, 0j, hi)
        if p1 != 0.0:
            _dm_depolarize_single(rho, size, target, p1)
    return rho


def _dm_pauli_expectation(rho: list[complex], size: int, observable: str) -> float:
    """计算 Tr(ρP)，P 由 Pauli 串给出，返回实部并规约到 [-1, 1]。"""
    flip = 0
    for q, ch in enumerate(observable):
        if ch in ("X", "Y"):
            flip |= 1 << q

    total = 0j
    for b in range(size):
        amp = rho[b * size + (b ^ flip)]
        if amp == 0j:
            continue
        phase = 1 + 0j
        for q, ch in enumerate(observable):
            bit = (b >> q) & 1
            if ch == "Y":
                phase *= -1j if bit else 1j
            elif ch == "Z":
                if bit:
                    phase = -phase
        total += amp * phase

    value = total.real
    if value > 1.0:
        return 1.0
    if value < -1.0:
        return -1.0
    return _canon_float(value)


# ---------------------------------------------------------------------------
# Pauli 期望值
# ---------------------------------------------------------------------------

def _pauli_expectation(state: list[complex], observable: str) -> float:
    """计算 ``⟨ψ|P|ψ⟩``，P 由 Pauli 串给出，返回实部并规约到 [-1, 1]。"""
    flip = 0
    for q, ch in enumerate(observable):
        if ch in ("X", "Y"):
            flip |= 1 << q

    total = 0j
    for b, amp in enumerate(state):
        if amp == 0j:
            continue
        c = b ^ flip
        phase = 1 + 0j
        for q, ch in enumerate(observable):
            bit = (c >> q) & 1
            if ch == "Y":
                phase *= -1j if bit else 1j
            elif ch == "Z":
                if bit:
                    phase = -phase
        total += amp.conjugate() * phase * state[c]

    value = total.real
    if value > 1.0:
        return 1.0
    if value < -1.0:
        return -1.0
    return _canon_float(value)


# ---------------------------------------------------------------------------
# 入口校验与估计
# ---------------------------------------------------------------------------

def _validate_observables(observables: Any, qubit_count: int) -> list[str]:
    if not isinstance(observables, list) or not observables:
        raise SimulationError(
            "invalid_observables", "observables",
            "observables must be a non-empty array of Pauli strings",
        )
    for i, obs in enumerate(observables):
        path = f"observables[{i}]"
        if not isinstance(obs, str):
            raise SimulationError("invalid_observable", path, f"observable at {path} must be a string")
        if len(obs) != qubit_count:
            raise SimulationError(
                "invalid_observable", path,
                f"observable at {path} must have length {qubit_count}",
            )
        if any(ch not in _PAULI_CHARS for ch in obs):
            raise SimulationError(
                "invalid_observable", path,
                f"observable at {path} may only contain I, X, Y, Z",
            )
    return list(observables)


def _validate_shots(shots: Any) -> int | None:
    if shots is None:
        return None
    if not _is_int(shots) or shots <= 0:
        raise SimulationError("invalid_shots", "shots", "shots must be a positive integer")
    return shots


def _validate_seed(seed: Any, shots: int | None) -> int | None:
    if shots is None:
        if seed is not None:
            raise SimulationError(
                "seed_without_shots", "seed",
                "seed is only meaningful together with shots",
            )
        return None
    if seed is None:
        return 0
    if not _is_int(seed) or seed < 0:
        raise SimulationError("invalid_seed", "seed", "seed must be a non-negative integer")
    return seed


def _validate_noise(noise: Any) -> tuple[float, float]:
    """校验噪声模型，返回 ``(single_qubit_depolarizing, two_qubit_depolarizing)``。

    ``noise`` 只能是 None 或对象；概率必须是排除 bool 的有限实数且在
    [0, 1] 内，缺省为 0.0。已提供概率按单比特、双比特顺序校验，最后
    拒绝未知字段（多个未知字段按字典序取首个）。
    """
    if noise is None:
        return 0.0, 0.0
    if not isinstance(noise, dict):
        raise SimulationError(
            "invalid_noise_model", "noise",
            "noise must be an object with optional depolarizing probabilities",
        )
    probs: list[float] = []
    for field in _NOISE_FIELDS:
        if field not in noise:
            probs.append(0.0)
            continue
        value = noise[field]
        path = f"noise.{field}"
        if not _is_number(value):
            raise SimulationError(
                "invalid_noise_model", path,
                f"probability at {path} must be a finite number in [0, 1]",
            )
        probability = float(value)
        if not math.isfinite(probability) or probability < 0.0 or probability > 1.0:
            raise SimulationError(
                "invalid_noise_model", path,
                f"probability at {path} must be a finite number in [0, 1]",
            )
        probs.append(probability)
    for key in noise:
        if not isinstance(key, str):
            raise SimulationError(
                "invalid_noise_model", "noise",
                "noise field names must be strings",
            )
    unknown = sorted(key for key in noise if key not in _NOISE_FIELD_SET)
    if unknown:
        name = unknown[0]
        raise SimulationError(
            "invalid_noise_model", f"noise.{name}",
            f"unknown noise field {name!r} at noise.{name}",
        )
    return probs[0], probs[1]


def estimate_expectation(
    circuit: Any,
    observables: Any,
    values: Any = None,
    shots: Any = None,
    seed: Any = None,
    noise: Any = None,
) -> dict:
    """估计电路末态上各 Pauli observable 的期望值，不修改输入。

    电路沿用现有校验与参数绑定语义；``shots`` 省略时返回精确期望值，
    否则每项独立采样并返回 ``{"positive", "negative"}`` 计数。返回
    ``{"qubit_count", "shots", "results"}``，其中 results 按 observables
    输入顺序排列，全部为 JSON 原生类型。

    ``noise`` 可给出逐门局部退极化概率（见模块文档）；任一概率非零时
    按含噪末态的密度矩阵求精确期望值，采样仍按含噪精确值进行。
    """
    bound = bind_parameters(circuit, {} if values is None else values)
    qubit_count = bound["qubit_count"]

    pauli_strings = _validate_observables(observables, qubit_count)
    p1, p2 = _validate_noise(noise)
    shot_count = _validate_shots(shots)
    resolved_seed = _validate_seed(seed, shot_count)

    noisy = p1 != 0.0 or p2 != 0.0
    max_qubits = _MAX_QUBITS_NOISY if noisy else _MAX_QUBITS
    if qubit_count > max_qubits:
        raise SimulationError(
            "state_space_too_large", "qubit_count",
            f"qubit_count {qubit_count} exceeds the {max_qubits}-qubit simulation limit",
        )

    if noisy:
        rho = _simulate_noisy(bound, p1, p2)
        size = 1 << qubit_count
        exact = [_dm_pauli_expectation(rho, size, obs) for obs in pauli_strings]
    else:
        state = _simulate(bound)
        exact = [_pauli_expectation(state, obs) for obs in pauli_strings]

    results: list[dict] = []
    if shot_count is None:
        for obs, value in zip(pauli_strings, exact):
            results.append({"observable": obs, "expectation": value})
    else:
        for i, (obs, value) in enumerate(zip(pauli_strings, exact)):
            rng = random.Random(f"{resolved_seed}:{i}")
            p_plus = (1.0 + value) / 2.0
            positive = sum(1 for _ in range(shot_count) if rng.random() < p_plus)
            negative = shot_count - positive
            results.append({
                "observable": obs,
                "expectation": _canon_float((positive - negative) / shot_count),
                "counts": {"positive": positive, "negative": negative},
            })

    return {"qubit_count": qubit_count, "shots": shot_count, "results": results}


# ---------------------------------------------------------------------------
# 参数移位梯度
# ---------------------------------------------------------------------------

_HALF_PI = math.pi / 2.0


def _simulate_with_shift(
    bound: dict,
    op_index: int,
    shift: float,
    p1: float = 0.0,
    p2: float = 0.0,
) -> list[complex]:
    """在绑定电路基础上把第 op_index 个旋转门角度平移 shift 后仿真。"""
    operations = [dict(op) for op in bound["operations"]]
    operations[op_index]["angle"] = operations[op_index]["angle"] + shift
    circuit = {
        "qubit_count": bound["qubit_count"],
        "parameters": [],
        "operations": operations,
    }
    if p1 != 0.0 or p2 != 0.0:
        return _simulate_noisy(circuit, p1, p2)
    return _simulate(circuit)


def estimate_gradient(circuit: Any, observables: Any, values: Any = None, noise: Any = None) -> dict:
    """精确参数移位梯度：各 observable 对全部声明参数的导数，不修改输入。

    校验与失败语义和精确 :func:`estimate_expectation` 一致。角度为
    ``aθ+b`` 的旋转门对参数 θ 的单次贡献为 ``a/2`` 乘以该门角度单独
    增减 ``π/2`` 后两次精确期望值之差；同一参数出现在多个旋转门时
    累加各门贡献，未用于参数化旋转的参数导数为 ``0.0``。``noise``
    非零时期望值与导数都按含噪密度矩阵精确计算（噪声通道与参数无关，
    参数移位规则保持不变）。

    返回 ``{"qubit_count", "parameters", "results"}``：parameters 保持
    声明顺序；results 保持 observables 输入顺序（含重复项），每项为
    ``{"observable", "expectation", "gradients"}``，gradients 按
    parameters 顺序给出浮点导数；所有输出把 ``-0.0`` 规范为 ``0.0``。
    """
    normalized = normalize_circuit(circuit)
    bound = bind_parameters(normalized, {} if values is None else values)
    qubit_count = bound["qubit_count"]

    pauli_strings = _validate_observables(observables, qubit_count)
    p1, p2 = _validate_noise(noise)

    noisy = p1 != 0.0 or p2 != 0.0
    max_qubits = _MAX_QUBITS_NOISY if noisy else _MAX_QUBITS
    if qubit_count > max_qubits:
        raise SimulationError(
            "state_space_too_large", "qubit_count",
            f"qubit_count {qubit_count} exceeds the {max_qubits}-qubit simulation limit",
        )

    parameters = list(normalized["parameters"])
    size = 1 << qubit_count

    if noisy:
        def _expect(sim_result: list[complex], obs: str) -> float:
            return _dm_pauli_expectation(sim_result, size, obs)

        base_state = _simulate_noisy(bound, p1, p2)
    else:
        def _expect(sim_result: list[complex], obs: str) -> float:
            return _pauli_expectation(sim_result, obs)

        base_state = _simulate(bound)
    base = [_expect(base_state, obs) for obs in pauli_strings]

    # 绑定前后操作一一对应；收集各参数出现的旋转门（下标与线性系数）。
    contributions: dict[str, list[tuple[int, float]]] = {name: [] for name in parameters}
    for i, op in enumerate(normalized["operations"]):
        angle = op.get("angle")
        if isinstance(angle, dict):
            contributions[angle["parameter"]].append((i, angle["coefficient"]))

    totals = {name: [0.0] * len(pauli_strings) for name in parameters}
    for name in parameters:
        for op_index, coefficient in contributions[name]:
            plus_state = _simulate_with_shift(bound, op_index, _HALF_PI, p1, p2)
            minus_state = _simulate_with_shift(bound, op_index, -_HALF_PI, p1, p2)
            factor = coefficient / 2.0
            for k, obs in enumerate(pauli_strings):
                plus = _expect(plus_state, obs)
                minus = _expect(minus_state, obs)
                totals[name][k] += factor * (plus - minus)

    results: list[dict] = []
    for k, obs in enumerate(pauli_strings):
        gradients = {name: _canon_float(totals[name][k]) for name in parameters}
        results.append({"observable": obs, "expectation": base[k], "gradients": gradients})

    return {"qubit_count": qubit_count, "parameters": parameters, "results": results}

import copy
import json
import math
import unittest

from qubitfabric.service import (
    CircuitValidationError,
    ParameterBindingError,
    Service,
    SimulationError,
)


def bind_err(fn, *args, **kwargs):
    try:
        fn(*args, **kwargs)
    except ParameterBindingError as exc:
        return exc
    raise AssertionError("ParameterBindingError not raised")


def sim_err(fn, *args, **kwargs):
    try:
        fn(*args, **kwargs)
    except SimulationError as exc:
        return exc
    raise AssertionError("SimulationError not raised")


class ExactGradientTest(unittest.TestCase):
    def setUp(self):
        self.svc = Service()

    def gradients(self, circuit, observables, values=None):
        result = self.svc.gradient(circuit, observables, values=values)
        return result

    def test_rx_z_gradient_matches_analytic(self):
        theta = 0.3
        circuit = {"qubit_count": 1, "parameters": ["theta"], "operations": [
            {"gate": "rx", "target": 0, "angle": {"parameter": "theta"}},
        ]}
        result = self.gradients(circuit, ["Z"], values={"theta": theta})
        item = result["results"][0]
        self.assertAlmostEqual(item["expectation"], math.cos(theta), places=12)
        self.assertAlmostEqual(item["gradients"]["theta"], -math.sin(theta), places=12)

    def test_rz_xy_gradients_match_analytic(self):
        theta = 0.7
        circuit = {"qubit_count": 1, "parameters": ["t"], "operations": [
            {"gate": "h", "target": 0},
            {"gate": "rz", "target": 0, "angle": {"parameter": "t"}},
        ]}
        result = self.gradients(circuit, ["X", "Y"], values={"t": theta})
        x_item, y_item = result["results"]
        self.assertAlmostEqual(x_item["expectation"], math.cos(theta), places=12)
        self.assertAlmostEqual(x_item["gradients"]["t"], -math.sin(theta), places=12)
        self.assertAlmostEqual(y_item["expectation"], math.sin(theta), places=12)
        self.assertAlmostEqual(y_item["gradients"]["t"], math.cos(theta), places=12)

    def test_coefficient_and_offset_scale_the_shift_rule(self):
        # 角度 2θ+0.1：Z 期望 cos(2θ+0.1)，导数 -2 sin(2θ+0.1)。
        theta = 0.4
        circuit = {"qubit_count": 1, "parameters": ["theta"], "operations": [
            {"gate": "rx", "target": 0,
             "angle": {"parameter": "theta", "coefficient": 2.0, "offset": 0.1}},
        ]}
        item = self.gradients(circuit, ["Z"], values={"theta": theta})["results"][0]
        angle = 2.0 * theta + 0.1
        self.assertAlmostEqual(item["expectation"], math.cos(angle), places=12)
        self.assertAlmostEqual(item["gradients"]["theta"], -2.0 * math.sin(angle), places=12)

    def test_negative_coefficient(self):
        theta = 0.9
        circuit = {"qubit_count": 1, "parameters": ["t"], "operations": [
            {"gate": "rx", "target": 0,
             "angle": {"parameter": "t", "coefficient": -1.5}},
        ]}
        item = self.gradients(circuit, ["Z"], values={"t": theta})["results"][0]
        angle = -1.5 * theta
        self.assertAlmostEqual(item["expectation"], math.cos(angle), places=12)
        self.assertAlmostEqual(item["gradients"]["t"], 1.5 * math.sin(angle), places=12)

    def test_shared_parameter_accumulates_gate_contributions(self):
        # 两个 rx 共用同一参数：总角 2θ，Z 期望 cos(2θ)，导数 -2 sin(2θ)。
        theta = 0.6
        circuit = {"qubit_count": 1, "parameters": ["t"], "operations": [
            {"gate": "rx", "target": 0, "angle": {"parameter": "t"}},
            {"gate": "rx", "target": 0, "angle": {"parameter": "t"}},
        ]}
        item = self.gradients(circuit, ["Z"], values={"t": theta})["results"][0]
        self.assertAlmostEqual(item["expectation"], math.cos(2.0 * theta), places=12)
        self.assertAlmostEqual(item["gradients"]["t"], -2.0 * math.sin(2.0 * theta), places=12)

    def test_unused_parameter_has_zero_gradient(self):
        circuit = {"qubit_count": 1, "parameters": ["used", "unused"], "operations": [
            {"gate": "rx", "target": 0, "angle": {"parameter": "used"}},
        ]}
        result = self.gradients(circuit, ["Z"], values={"used": 0.5, "unused": 1.25})
        self.assertEqual(result["parameters"], ["used", "unused"])
        gradients = result["results"][0]["gradients"]
        self.assertEqual(list(gradients), ["used", "unused"])
        self.assertEqual(gradients["unused"], 0.0)
        self.assertAlmostEqual(gradients["used"], -math.sin(0.5), places=12)

    def test_constant_angles_and_other_gates_contribute_nothing(self):
        circuit = {"qubit_count": 2, "parameters": ["t"], "operations": [
            {"gate": "x", "target": 0},
            {"gate": "rx", "target": 0, "angle": 0.25},
            {"gate": "h", "target": 1},
            {"gate": "cx", "control": 0, "target": 1},
            {"gate": "rz", "target": 1, "angle": {"parameter": "t"}},
        ]}
        result = self.gradients(circuit, ["ZZ", "XI"], values={"t": 0.8})
        # 与 svc.expectation 的精确值一致。
        exact = self.svc.expectation(circuit, ["ZZ", "XI"], values={"t": 0.8})
        for got, want in zip(result["results"], exact["results"]):
            self.assertEqual(got["expectation"], want["expectation"])

    def test_results_keep_observable_order_and_duplicates(self):
        circuit = {"qubit_count": 1, "parameters": ["t"], "operations": [
            {"gate": "rx", "target": 0, "angle": {"parameter": "t"}},
        ]}
        result = self.gradients(circuit, ["Z", "X", "Z"], values={"t": 0.3})
        self.assertEqual([r["observable"] for r in result["results"]], ["Z", "X", "Z"])
        self.assertEqual(result["results"][0], result["results"][2])
        self.assertEqual(result["qubit_count"], 1)

    def test_no_parameter_circuit_allows_omitted_or_empty_values(self):
        circuit = {"qubit_count": 1, "operations": [{"gate": "h", "target": 0}]}
        omitted = self.svc.gradient(circuit, ["X"])
        empty = self.svc.gradient(circuit, ["X"], values={})
        self.assertEqual(omitted, empty)
        self.assertEqual(omitted["parameters"], [])
        self.assertEqual(omitted["results"][0]["gradients"], {})
        self.assertAlmostEqual(omitted["results"][0]["expectation"], 1.0, places=12)

    def test_zero_qubit_circuit(self):
        result = self.svc.gradient({"qubit_count": 0}, [""])
        self.assertEqual(result["results"], [
            {"observable": "", "expectation": 1.0, "gradients": {}},
        ])

    def test_gradient_matches_central_finite_difference(self):
        circuit = {"qubit_count": 2, "parameters": ["a", "b"], "operations": [
            {"gate": "rx", "target": 0,
             "angle": {"parameter": "a", "coefficient": 2.0, "offset": 0.3}},
            {"gate": "h", "target": 1},
            {"gate": "rz", "target": 1,
             "angle": {"parameter": "b", "coefficient": -0.5}},
            {"gate": "cx", "control": 0, "target": 1},
            {"gate": "rx", "target": 1, "angle": {"parameter": "a"}},
            {"gate": "rz", "target": 0, "angle": 0.7},
        ]}
        observables = ["ZZ", "XI", "IY", "YX"]
        values = {"a": 0.4, "b": 1.1}
        result = self.svc.gradient(circuit, observables, values=values)

        eps = 1e-6
        for k, item in enumerate(result["results"]):
            for name in ("a", "b"):
                plus = dict(values, **{name: values[name] + eps})
                minus = dict(values, **{name: values[name] - eps})
                e_plus = self.svc.expectation(circuit, observables, values=plus)["results"][k]["expectation"]
                e_minus = self.svc.expectation(circuit, observables, values=minus)["results"][k]["expectation"]
                numeric = (e_plus - e_minus) / (2.0 * eps)
                self.assertAlmostEqual(item["gradients"][name], numeric, places=5)

    def test_input_not_mutated_and_result_json_serializable(self):
        circuit = {"qubit_count": 1, "parameters": ["t"], "operations": [
            {"gate": "rx", "target": 0, "angle": {"parameter": "t"}},
        ]}
        observables = ["Z", "X"]
        values = {"t": 0.5}
        snapshot = (copy.deepcopy(circuit), list(observables), dict(values))
        result = self.svc.gradient(circuit, observables, values=values)
        self.assertEqual((circuit, observables, values), snapshot)
        payload = json.dumps(result, sort_keys=True)
        self.assertNotIn("-0.0", payload)


class GradientValidationTest(unittest.TestCase):
    def setUp(self):
        self.svc = Service()
        self.circuit = {"qubit_count": 1, "parameters": ["theta"], "operations": [
            {"gate": "rz", "target": 0, "angle": {"parameter": "theta"}},
        ]}

    def test_circuit_validation_is_reused(self):
        with self.assertRaises(CircuitValidationError):
            self.svc.gradient({"qubit_count": 1, "operations": [{"gate": "x", "target": 5}]}, ["Z"])

    def test_missing_and_unknown_parameter_raise_binding_error(self):
        e = bind_err(self.svc.gradient, self.circuit, ["Z"])
        self.assertEqual((e.code, e.path), ("missing_parameter", "theta"))
        e = bind_err(self.svc.gradient, {"qubit_count": 1}, ["Z"], values={"nope": 1})
        self.assertEqual((e.code, e.path), ("unknown_parameter", "nope"))

    def test_invalid_values_type_and_non_finite(self):
        e = bind_err(self.svc.gradient, self.circuit, ["Z"], values=[("theta", 1.0)])
        self.assertEqual((e.code, e.path), ("invalid_type", "$"))
        e = bind_err(self.svc.gradient, self.circuit, ["Z"], values={"theta": "x"})
        self.assertEqual((e.code, e.path), ("invalid_type", "theta"))
        e = bind_err(self.svc.gradient, self.circuit, ["Z"], values={"theta": math.inf})
        self.assertEqual((e.code, e.path), ("non_finite_number", "theta"))

    def test_observables_must_be_non_empty_array(self):
        for bad in (None, "Z", {"0": "Z"}, [], 1):
            with self.subTest(bad=bad):
                e = sim_err(self.svc.gradient, {"qubit_count": 1}, bad)
                self.assertEqual((e.code, e.path), ("invalid_observables", "observables"))

    def test_invalid_observable_items(self):
        for observables, path in [(["Z", 1], "observables[1]"), (["ZZ"], "observables[0]"), (["z"], "observables[0]")]:
            with self.subTest(observables=observables):
                e = sim_err(self.svc.gradient, {"qubit_count": 1}, observables)
                self.assertEqual((e.code, e.path), ("invalid_observable", path))

    def test_state_space_too_large(self):
        e = sim_err(self.svc.gradient, {"qubit_count": 21}, ["I" * 21])
        self.assertEqual((e.code, e.path), ("state_space_too_large", "qubit_count"))
        result = self.svc.gradient({"qubit_count": 20}, ["I" * 20])
        self.assertEqual(result["results"][0]["expectation"], 1.0)

    def test_validation_order_matches_expectation(self):
        # 电路错误先于绑定错误，绑定错误先于 observables 错误。
        bad_circuit = {"qubit_count": 1, "operations": [{"gate": "x", "target": 5}]}
        with self.assertRaises(CircuitValidationError):
            self.svc.gradient(bad_circuit, [], values={"theta": 1})
        e = bind_err(self.svc.gradient, self.circuit, [])
        self.assertEqual(e.code, "missing_parameter")


